class MyClass { // Non-trivial initialization and destruction
    public:
    MyClass() { /* Constructor body; compiler inserts code to initialize members */ } // Implementation note: Compiler generates a function for this, called at runtime when object is created.
    ~MyClass() { /* Destructor body; compiler ensures this is called at end of lifetime */ } // Implementation note: For stack objects, compiler adds code to invoke this in the scope's epilogue; for heap objects, it's paired with delete.
};

MyClass obj; // Automatic storage: Compiler allocates stack space and calls MyClass::MyClass() at runtime.
MyClass* ptr = new MyClass(); // Dynamic storage: Compiler calls operator new for memory, then MyClass::MyClass(); note: operator new's failure (e.g., out-of-memory) is runtime behavior.
